do $$ declare r record; begin for r in select p.proname,pg_get_functiondef(p.oid) def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('send_game_challenge','respond_game_challenge','get_game_leaderboard','get_friend_game_leaderboard') loop execute replace(r.def,'FUNCTION public.'||r.proname,'FUNCTION zuno_private.'||r.proname); end loop; end $$;
create or replace function public.send_game_challenge(p_friend_id uuid,p_game_id text,p_target_score integer default 0,p_message text default null) returns uuid language sql security invoker set search_path='' as $$ select zuno_private.send_game_challenge(p_friend_id,p_game_id,p_target_score,p_message) $$;
create or replace function public.respond_game_challenge(p_challenge_id uuid,p_accept boolean) returns table(challenge_id uuid,game_id text,target_score integer,status text) language sql security invoker set search_path='' as $$ select * from zuno_private.respond_game_challenge(p_challenge_id,p_accept) $$;
create or replace function public.get_game_leaderboard(p_limit integer default 25) returns table(rank bigint,user_id uuid,username text,avatar_url text,game_level integer,xp integer,total_games integer,total_wins integer,best_score integer) language sql stable security invoker set search_path='' as $$ select * from zuno_private.get_game_leaderboard(p_limit) $$;
create or replace function public.get_friend_game_leaderboard(p_limit integer default 25) returns table(rank bigint,user_id uuid,username text,avatar_url text,game_level integer,xp integer,total_games integer,total_wins integer,best_score integer) language sql stable security invoker set search_path='' as $$ select * from zuno_private.get_friend_game_leaderboard(p_limit) $$;
grant usage on schema zuno_private to authenticated,service_role;
do $$ declare f regprocedure; begin foreach f in array array['public.send_game_challenge(uuid,text,integer,text)'::regprocedure,'public.respond_game_challenge(uuid,boolean)'::regprocedure,'public.get_game_leaderboard(integer)'::regprocedure,'public.get_friend_game_leaderboard(integer)'::regprocedure,'zuno_private.send_game_challenge(uuid,text,integer,text)'::regprocedure,'zuno_private.respond_game_challenge(uuid,boolean)'::regprocedure,'zuno_private.get_game_leaderboard(integer)'::regprocedure,'zuno_private.get_friend_game_leaderboard(integer)'::regprocedure] loop execute format('revoke all on function %s from public, anon',f); execute format('grant execute on function %s to authenticated, service_role',f); end loop; end $$;
